h q[0];
barrier q[2];

// 4. Coherent deferred-measurement Pauli frame feed-forward onto Bob q[2]
cx q[1], q[2];
cz q[0], q[2];

c[0] = measure q[0];
c[1] = measure q[1];
c[2] = measure q[2];

